```
unsigned long onceki = 0;

void setup() {
  pinMode(13, OUTPUT);
}

void loop() {
  unsigned long simdi = millis();
  if (simdi >= onceki + 500) {
    onceki = simdi;
    digitalWrite(13, !digitalRead(13));
  }
}
```
